                ["`AUTH_LOCKOUT_DURATION`", "`15m`", "How long an account stays locked"],
                ["`AUTH_IP_RATE_LIMIT`", "`20`", "Failed sign-ins and unknown tokens per address before it's blocked (until saved in Settings → Security → Rate limits)"],
