                ["`AUTH_PASSWORD_MIN_LENGTH`", "`12`", "Minimum password length (8–64)"],
                ["`AUTH_SESSION_LIFETIME`", "`24h`", "Longest session without **Remember me** (until saved in Settings → Security → Sessions)"],
                ["`AUTH_REMEMBER_SESSION_LIFETIME`", "`168h`", "Longest session with **Remember me**"],
                ["`AUTH_MAX_SESSIONS`", "`5`", "Sessions per person"],
                ["`AUTH_REFRESH_LIFETIME`, `AUTH_REMEMBER_REFRESH_LIFETIME`, `AUTH_REFRESH_GRACE_PERIOD`", "built in", "Lifetimes of the browser's refresh tokens; leave them unless support asks"],
                ["`AUTH_COOKIE_DOMAIN`", "the host", "Domain of the session cookies"],
                ["`AUTH_COOKIE_SECURE`", "`true`", "Session cookies are sent over HTTPS only. `false` only for a local test over plain HTTP"],
                ["`AUTH_PASSWORD_RESET_TTL`", "`30m`", "Password reset link lifetime (5m–24h)"],
                ["`AUTH_INVITATION_TTL`", "`168h`", "Invitation link lifetime (1h–720h)"],
                ["`AUTH_LOGIN_HISTORY_RETENTION_DAYS`", "`90`", "Days of login history kept"],
                ["`AUTH_CLEANUP_RETENTION_DAYS`", "built in", "Days expired sessions and tokens are kept before cleanup"],
                ["`SSO_ENFORCEMENT_OVERRIDE`", "`false`", "**Emergency only**: `true` ignores **Require single sign-on** on this server so an administrator can sign in with a password while the identity provider is down. Remove it afterwards"],
