                ["`DOWNLOAD_QUOTAS_ENABLED`", "`false`", "Daily and monthly download quotas (Pro)"],
                ["`DOWNLOAD_QUOTA_USER_GIB_PER_DAY`, `…_PER_MONTH`", "`0` (none)", "Per signed-in person (GiB)"],
